$\Lim\!\left(\dfrac{n^3}{n+1} - \dfrac{n^2}{n+2}\right)
        = \Lim\dfrac{n^3(n+2) - n^2(n+1)}{(n+1)(n+2)}
        = \Lim\dfrac{n^4+n^3-n^2}{n^2+3n+2} = \boldsymbol{+\infty}$ <br>  (el numerador té grau 4 i el denominador, 2)

$\Lim\!\left(\dfrac{kn^2+1}{n+1} - \dfrac{3n^2}{n-1}\right)
        = \Lim\dfrac{(kn^2+1)(n-1) - 3n^2(n+1)}{(n+1)(n-1)}
        = \Lim\dfrac{(k-3)n^3 - (k+3)n^2 + n - 1}{n^2-1}$ <br> El denominador té grau 2, o sigui que el numerador no en pot tenir 3: cal $k-3 = 0$, és a dir $\boldsymbol{k = 3}$. Amb aquest valor, $\Lim\dfrac{-6n^2+n-1}{n^2-1} = \mathbf{-6}$.

$\Lim\!\left(\dfrac{n^2+kn}{n+1} - \dfrac{n^2}{n+2}\right)
        = \Lim\dfrac{(n^2+kn)(n+2) - n^2(n+1)}{(n+1)(n+2)}
        = \Lim\dfrac{(k+1)n^2 + 2kn}{n^2+3n+2} = k+1$ <br> Per tant $k+1 = 5$, és a dir $\boldsymbol{k = 4}$.

$\Lim\!\left(\sqrt{kn^2+3n} - 2n\right)
        = \Lim\dfrac{(kn^2+3n)-4n^2}{\sqrt{kn^2+3n}+2n}
        = \Lim\dfrac{(k-4)n^2+3n}{\left(\sqrt{k}+2\right)n}$ <br> Perquè el límit sigui finit cal $k = 4$, i llavors $\Lim\dfrac{3n}{\left(\sqrt{4}+2\right)n} = \dfrac{3}{4}$ ✓. Per tant $\boldsymbol{k = 4}$.

\[
  \begin{aligned}
  \Lim\left(1+\dfrac{1}{n}\right)^{n} &= 1^{+\infty} = \text{ind}\\
  \Lim\left(1+\dfrac{1}{n}\right)^{n} &= e \quad\text{(és la definició del nombre $e$, amb $A=n$)}
  \end{aligned}
  \]

\[
  \begin{aligned}
  \Lim\left(\dfrac{2n^2+k}{2n^2+5}\right)^{n^2} &= 1^{+\infty} = \text{ind}\\
  \Lim\left(\dfrac{2n^2+k}{2n^2+5}\right)^{n^2} &= \Lim\left(1+\dfrac{2n^2+k}{2n^2+5}-1\right)^{n^2}
  = \Lim\left(1+\dfrac{k-5}{2n^2+5}\right)^{n^2}\\
  &= \Lim\left(1+\dfrac{1}{\frac{2n^2+5}{k-5}}\right)^{n^2}\\
  &= \Lim\left(1+\dfrac{1}{\frac{2n^2+5}{k-5}}\right)^{n^2\cdot\frac{2n^2+5}{k-5}\cdot\frac{k-5}{2n^2+5}}\\
  &= e^{\Lim n^2\cdot\frac{k-5}{2n^2+5}} = e^{\Lim\frac{(k-5)n^2}{2n^2+5}} = e^{\frac{k-5}{2}}
  \end{aligned}
  \] Igualem: $e^{\frac{k-5}{2}} = e^{3} \;\Rightarrow\; \dfrac{k-5}{2} = 3 \;\Rightarrow\; k = 11$.

\[
  \begin{aligned}
  \Lim\left(1+\dfrac{k}{n}\right)^{n+3} &= 1^{+\infty} = \text{ind}\\
  \Lim\left(1+\dfrac{k}{n}\right)^{n+3} &= \Lim\left(1+\dfrac{1}{\frac{n}{k}}\right)^{n+3}
  = \Lim\left(1+\dfrac{1}{\frac{n}{k}}\right)^{(n+3)\cdot\frac{n}{k}\cdot\frac{k}{n}}\\
  &= e^{\Lim (n+3)\cdot\frac{k}{n}} = e^{\Lim\frac{kn+3k}{n}} = e^{k}
  \end{aligned}
  \] Igualem: $e^{k} = e^{2} \;\Rightarrow\; k = 2$.

\[
  \begin{aligned}
  \Lim\left(\dfrac{n-1}{n+3}\right)^{kn} &= 1^{+\infty} = \text{ind}\\
  \Lim\left(\dfrac{n-1}{n+3}\right)^{kn} &= \Lim\left(1+\dfrac{n-1}{n+3}-1\right)^{kn}
  = \Lim\left(1+\dfrac{n-1-(n+3)}{n+3}\right)^{kn}\\
  &= \Lim\left(1+\dfrac{-4}{n+3}\right)^{kn}
  = \Lim\left(1+\dfrac{1}{\frac{n+3}{-4}}\right)^{kn}\\
  &= \Lim\left(1+\dfrac{1}{\frac{n+3}{-4}}\right)^{kn\cdot\frac{n+3}{-4}\cdot\frac{-4}{n+3}}\\
  &= e^{\Lim kn\cdot\frac{-4}{n+3}} = e^{\Lim\frac{-4kn}{n+3}} = e^{-4k}
  \end{aligned}
  \] Igualem: $e^{-4k} = e^{2} \;\Rightarrow\; -4k = 2 \;\Rightarrow\; k = -\dfrac{1}{2}$.

\[
  \begin{aligned}
  \Lim\left(\dfrac{3n+k}{3n-1}\right)^{2n+5} &= 1^{+\infty} = \text{ind}\\
  \Lim\left(\dfrac{3n+k}{3n-1}\right)^{2n+5} &= \Lim\left(1+\dfrac{3n+k}{3n-1}-1\right)^{2n+5}
  = \Lim\left(1+\dfrac{3n+k-(3n-1)}{3n-1}\right)^{2n+5}\\
  &= \Lim\left(1+\dfrac{k+1}{3n-1}\right)^{2n+5}
  = \Lim\left(1+\dfrac{1}{\frac{3n-1}{k+1}}\right)^{2n+5}\\
  &= \Lim\left(1+\dfrac{1}{\frac{3n-1}{k+1}}\right)^{(2n+5)\cdot\frac{3n-1}{k+1}\cdot\frac{k+1}{3n-1}}\\
  &= e^{\Lim (2n+5)\cdot\frac{k+1}{3n-1}} = e^{\Lim\frac{(2k+2)n+5k+5}{3n-1}} = e^{\frac{2(k+1)}{3}}
  \end{aligned}
  \] Igualem: $e^{\frac{2(k+1)}{3}} = e^{4} \;\Rightarrow\; \dfrac{2(k+1)}{3} = 4 \;\Rightarrow\; k+1 = 6 \;\Rightarrow\; k = 5$.

\[
  \begin{aligned}
  \Lim\left(\dfrac{n+a}{n+b}\right)^{n} &= 1^{+\infty} = \text{ind}\\
  \Lim\left(\dfrac{n+a}{n+b}\right)^{n} &= \Lim\left(1+\dfrac{n+a}{n+b}-1\right)^{n}
  = \Lim\left(1+\dfrac{a-b}{n+b}\right)^{n}
  = \Lim\left(1+\dfrac{1}{\frac{n+b}{a-b}}\right)^{n}\\
  &= \Lim\left(1+\dfrac{1}{\frac{n+b}{a-b}}\right)^{n\cdot\frac{n+b}{a-b}\cdot\frac{a-b}{n+b}}
  = e^{\Lim n\cdot\frac{a-b}{n+b}} = e^{\Lim\frac{(a-b)n}{n+b}} = e^{a-b}
  \end{aligned}
  \] Igualem: $e^{a-b} = e^{-4} \;\Rightarrow\; a - b = -4$.

\[
  \begin{aligned}
  \Lim\left(\dfrac{an+1}{an-2}\right)^{bn} &= 1^{+\infty} = \text{ind}\\
  \Lim\left(\dfrac{an+1}{an-2}\right)^{bn} &= \Lim\left(1+\dfrac{an+1}{an-2}-1\right)^{bn}
  = \Lim\left(1+\dfrac{an+1-(an-2)}{an-2}\right)^{bn}\\
  &= \Lim\left(1+\dfrac{3}{an-2}\right)^{bn}
  = \Lim\left(1+\dfrac{1}{\frac{an-2}{3}}\right)^{bn}\\
  &= \Lim\left(1+\dfrac{1}{\frac{an-2}{3}}\right)^{bn\cdot\frac{an-2}{3}\cdot\frac{3}{an-2}}\\
  &= e^{\Lim bn\cdot\frac{3}{an-2}} = e^{\Lim\frac{3bn}{an-2}} = e^{\frac{3b}{a}}
  \end{aligned}
  \] Igualem: $e^{\frac{3b}{a}} = e^{6} \;\Rightarrow\; \dfrac{3b}{a} = 6 \;\Rightarrow\; b = 2a$  (amb $a\neq 0$).

\[
  \begin{aligned}
  \Lim\left(\dfrac{n^2+a}{n^2+b}\right)^{2n^2} &= 1^{+\infty} = \text{ind}\\
  \Lim\left(\dfrac{n^2+a}{n^2+b}\right)^{2n^2} &= \Lim\left(1+\dfrac{n^2+a}{n^2+b}-1\right)^{2n^2}
  = \Lim\left(1+\dfrac{a-b}{n^2+b}\right)^{2n^2}\\
  &= \Lim\left(1+\dfrac{1}{\frac{n^2+b}{a-b}}\right)^{2n^2}\\
  &= \Lim\left(1+\dfrac{1}{\frac{n^2+b}{a-b}}\right)^{2n^2\cdot\frac{n^2+b}{a-b}\cdot\frac{a-b}{n^2+b}}\\
  &= e^{\Lim 2n^2\cdot\frac{a-b}{n^2+b}} = e^{\Lim\frac{2(a-b)n^2}{n^2+b}} = e^{2(a-b)}
  \end{aligned}
  \] Igualem: $e^{2(a-b)} = e^{-2} \;\Rightarrow\; 2(a-b) = -2 \;\Rightarrow\; a - b = -1$.

\[
  \begin{aligned}
  \Lim\left(\dfrac{n+a}{n}\right)^{bn} &= 1^{+\infty} = \text{ind}\\
  \Lim\left(\dfrac{n+a}{n}\right)^{bn} &= \Lim\left(1+\dfrac{n+a}{n}-1\right)^{bn}
  = \Lim\left(1+\dfrac{a}{n}\right)^{bn}
  = \Lim\left(1+\dfrac{1}{\frac{n}{a}}\right)^{bn}\\
  &= \Lim\left(1+\dfrac{1}{\frac{n}{a}}\right)^{bn\cdot\frac{n}{a}\cdot\frac{a}{n}}
  = e^{\Lim bn\cdot\frac{a}{n}} = e^{\Lim\frac{abn}{n}} = e^{ab}
  \end{aligned}
  \] Igualem: $e^{ab} = e^{6} \;\Rightarrow\; ab = 6$.

La base tendeix a $+\infty$ i l'exponent a $\Lim\dfrac{2-4n}{2n+1} = -2$: \[
  \Lim\left(n^2+1\right)^{\frac{2-4n}{2n+1}} = (+\infty)^{-2} = \dfrac{1}{(+\infty)^2} = \mathbf{0}
  \]

Les dues fraccions ja tenen el mateix denominador: \[
  \begin{aligned}
  &\Lim\left(\dfrac{(n^3+2)^2}{n^3} - \dfrac{(n^3-2)^2}{n^3}\right)\\
  &= \Lim\dfrac{(n^6+4n^3+4)-(n^6-4n^3+4)}{n^3}
  = \Lim\dfrac{8n^3}{n^3} = \mathbf{8}
  \end{aligned}
  \]

\[
  \begin{aligned}
  \Lim\left(1+\dfrac{1}{n}\right)^{n^2} &= 1^{+\infty} = \text{ind}\\
  \Lim\left(1+\dfrac{1}{n}\right)^{n^2} &= \Lim\left(1+\dfrac{1}{n}\right)^{n^2\cdot n\cdot\frac{1}{n}}\\
  &= e^{\Lim n^2\cdot\frac{1}{n}} = e^{\Lim n} = e^{+\infty} = \mathbf{+\infty}
  \end{aligned}
  \]

\[
  \begin{aligned}
  \Lim\left(\dfrac{n+k}{n-1}\right)^{n} &= 1^{+\infty} = \text{ind}\\
  \Lim\left(\dfrac{n+k}{n-1}\right)^{n} &= \Lim\left(1+\dfrac{n+k}{n-1}-1\right)^{n}
  = \Lim\left(1+\dfrac{k+1}{n-1}\right)^{n}
  = \Lim\left(1+\dfrac{1}{\frac{n-1}{k+1}}\right)^{n}\\
  &= \Lim\left(1+\dfrac{1}{\frac{n-1}{k+1}}\right)^{n\cdot\frac{n-1}{k+1}\cdot\frac{k+1}{n-1}}\\
  &= e^{\Lim n\cdot\frac{k+1}{n-1}} = e^{\Lim\frac{(k+1)n}{n-1}} = e^{k+1}
  \end{aligned}
  \] Igualem: $e^{k+1} = e^{3} \;\Rightarrow\; k+1 = 3 \;\Rightarrow\; \mathbf{k = 2}$.
